      SecretId: 'prod/mongodb-atlas-creds'
    }).promise();

    const { username, password } = JSON.parse(secretData.SecretString);
    const MONGODB_URI = process.env.MONGODB_URI.replace('<username>:<password>', `${encodeURIComponent(username)}:${encodeURIComponent(password)}`);

