#### 🔹 Profile Update Logic (`profileController.js`)
```javascript
const { getDatabase } = require('./dbConnection');
const validator = require('validator');
const sanitize = require('mongo-sanitize');

exports.updateProfile = async (req, res) => {
  const userId = req.user.sub; // From JWT
  const { email, name, phone } = sanitize(req.body);

  console.log(`[${new Date().toISOString()}] PROFILE-UPDATE: Initiated by user: ${userId}`);

  // Validation
  if (email && !validator.isEmail(email)) {
    console.log(`[${new Date().toISOString()}] VALIDATION-ERROR: Invalid email - ${email}`);
    return res.status(400).json({
      status: "error",
      message: "Invalid email format"
    });
  }

  if (name && validator.isEmpty(name.trim()) || (name && name.length > 100)) {
    return res.status(400).json({
      status: "error",
      message: "Name must be 1–100 characters"
    });
  }

  if (phone && !validator.isMobilePhone(phone, 'any', { strictMode: false })) {
    return res.status(400).json({
      status: "error",
      message: "Phone number must be in E.164 format"
    });
  }

  try {
    const db = await getDatabase();
    const collection = db.collection('profiles');

    const updateFields = {};
    if (email) updateFields.email = email.toLowerCase();
    if (name) updateFields.name = name.trim();
    if (phone) updateFields.phone = phone;

    const result = await collection.updateOne(
      { userId },
      { $set: updateFields },
      { upsert: false } // Per requirements: do not auto-create
    );

    if (result.matchedCount === 0) {
      console.log(`[${new Date().toISOString()}] DB-WARN: No profile found for user ${userId}`);
      return res.status(404).json({
        status: "error",
        message: "User profile not found"
      });
    }

    console.log(`[${new Date().toISOString()}] PROFILE-SUCCESS: Updated profile for user ${userId}`);
    res.status(200).json({
      status: "success",
      message: "Profile updated successfully"
    });

  } catch (error) {
    console.error(`[${new Date().toISOString()}] DB-ERROR: Update failed for user ${userId} - ${error.message}`);
    res.status(500).json({
      status: "error",
      message: "Database update failed"
    });
  }
};
```

